import{_ as e,c as a,o as r,a4 as t}from"./chunks/framework.D5y910bP.js";const h=JSON.parse('{"title":"Supabase Cloudflare project builder","description":"","frontmatter":{"date":"2023-09-04T00:00:00.000Z","tags":["cloudflare","supabase","cloudflare workers","template"],"title":"Supabase Cloudflare project builder"},"headers":[],"relativePath":"blog/supabase-cf-project-builder.md","filePath":"blog/supabase-cf-project-builder.md","lastUpdated":1739289997000}'),s={name:"blog/supabase-cf-project-builder.md"},o=t('<h1 id="supabase-cloudflare-project-builder" tabindex="-1">Supabase Cloudflare project builder <a class="header-anchor" href="#supabase-cloudflare-project-builder" aria-label="Permalink to &quot;Supabase Cloudflare project builder&quot;">​</a></h1><p>Generic Project Management backend using Supabase and Cloudflare.</p><p>Simple starter kit for the backend that can also be used as is to create a project management system similar to figma(without realtime collaboration right now) with supabase and cloudflare workers.</p><p>Database in supabase, file storage in r2, proxy using cloudflare workers, basic stripe integration.</p><p>Note: This is a very simple project and could serve as a starting point. But this in no way is a complete production ready system, and requires considerable work on the frontend.</p><p>Github - <a href="https://github.com/repalash/supabase-cf-project-starter" target="_blank" rel="noreferrer">https://github.com/repalash/supabase-cf-project-starter</a></p><p>I am using it for several tools partly/fully in <a href="https://hdrmap.com" target="_blank" rel="noreferrer">hdrmap.com</a>, <a href="https://ijewel.design" target="_blank" rel="noreferrer">ijewel.design</a>, <a href="https://ijewel.studio" target="_blank" rel="noreferrer">ijewel.studio</a> and some more.</p>',7),l=[o];function i(p,n,c,d,u,b){return r(),a("div",null,l)}const m=e(s,[["render",i]]);export{h as __pageData,m as default};
